   [29]={next_id=30, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这些红点是什么？", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [30]={next_id=31, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是维里塔的十三个克隆体，它们拥有着与维里塔相同的容貌，并借助奥尼弗尔其他的机械守卫建立链接，从而让她可以完成意识转移。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [31]={next_id=32, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她紧接着又拿出来一些药剂，与她先前装到手套里的那种溶液颇为相似。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [32]={next_id=33, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="深海立刻猜到了丽娜的目的。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我看到过您的笔记……提到了某种神经毒素。", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [34]={next_id=35, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="之前我也让啫喱用它在克里安卡的克隆体身上尝试过过，您是要让我用这种东西阻断维里塔的逃脱之路？", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [35]={next_id=36, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是的，我研究这种东西很多年了，维里塔很狡猾，从上次死里逃生后，她就开始为自己下一次危机做准备。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206},{ 3, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="要杀死她同样艰难，她如今的生命来自某样神奇的物质——用外面通用的称呼就是封禁物，倘若将她杀死，她同样会变成一只怪物。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206},{ 3, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="深海见过那样子的场面，那还是在黎苏根，眼前这个人的某个克隆体在他们面前变成了一个异变体。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206},{ 3, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就像是FL-218那样，但这只是维里塔迫不得已的一步，在那之前她会先通过数据网络将自己的意识转移至某个备用身躯上。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206},{ 3, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以您才要研究那种神经毒素，然后让她作为中转的机械失效，无处逃脱。", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206},{ 3, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
