   [110]={next_id=111, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他曾拒绝过我两次，所以我早已做好了谈判失败的准备。", msg_color="", msg_size=0, talker="维里塔", audio="", img="arts/ui/bg/story/storybg_ACT201_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7211", 0, 0, -10.5, 190}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [111]={next_id=112, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她叹着气，一边向后退了些，却被什么东西拦住了——是丽娜，她人和轮椅一起挡在那儿。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7211", 0, 0, -10.5, 190}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
